import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        sc.nextLine();
        String line = sc.nextLine();

        StringBuilder builder = new StringBuilder();
        int countInParentheses = 0;
        int index = 0;

        while (index < line.length()) {
            if (line.charAt(index) == '(') {
                builder.append('_');
                index++;
                StringBuilder inside = new StringBuilder();
                while (line.charAt(index) != ')') {
                    inside.append(line.charAt(index));
                    index++;
                }
                String[] wordsInside = inside.toString().split("_");
                for (String word : wordsInside) {
                    if (!word.isEmpty()) {
                        countInParentheses++;
                    }
                }
            } else {
                builder.append(line.charAt(index));
            }
            index++;
        }

        String[] parts = builder.toString().split("_");
        int maxWordLength = 0;
        for (String part : parts) {
            if (!part.isEmpty() && part.length() > maxWordLength) {
                maxWordLength = part.length();
            }
        }

        System.out.println(maxWordLength + " " + countInParentheses);
        sc.close();
    }
}
