#include <iostream>
#include <string>
#include <vector>
#include <sstream>

int main() {
    int n;
    std::cin >> n;
    std::cin.ignore(); // ignore the remaining newline after reading n
    std::string line;
    std::getline(std::cin, line);

    std::string builder;
    int countInParentheses = 0;
    size_t index = 0;

    while (index < line.length()) {
        if (line[index] == '(') {
            builder += '_';
            index++;
            std::string inside;
            while (index < line.length() && line[index] != ')') {
                inside += line[index];
                index++;
            }
            // Skip the closing parenthesis
            if (index < line.length() && line[index] == ')') {
                index++;
            }
            std::istringstream iss(inside);
            std::string word;
            while (iss >> word) {
                if (!word.empty()) {
                    countInParentheses++;
                }
            }
        } else {
            builder += line[index];
            index++;
        }
    }

    std::istringstream ss(builder);
    std::string part;
    int maxWordLength = 0;
    while (ss >> part) {
        if (!part.empty() && (int)part.length() > maxWordLength) {
            maxWordLength = part.length();
        }
    }

    std::cout << maxWordLength << " " << countInParentheses << std::endl;
    return 0;
}
